pragma solidity 0.8.22;
contract ClockGate {
 function allowed(uint256 deadline) external view returns (bool) {
  require(block.timestamp >= deadline, "wait");
  return true;
 }
}

pragma solidity 0.8.22;
contract Arithmetic {
 function add(uint256 a, uint256 b) external pure returns (uint256) {
  return a + b;
 }
}
